import {esc,plain,words} from './text.js';
import {DraftFlow,flowAxes,axisLabel,wordPrefix} from './draft-flow.js';
const paths={pin:'m14 3 7 7-3 1-3 5-3-3-7 7m3-8-3-3 5-3 1-3Z',arrow:'M4 12h16m-5-5 5 5-5 5',stop:'M6 6h12v12H6z',check:'m5 12 4 4L20 5',copy:'M8 8h13v13H8z M16 8V3H3v13h5',close:'m6 6 12 12M6 18 18 6',refresh:'M20 5v6h-6M4 19v-6h6M5 9a8 8 0 0 1 13-4l2 3M4 16l2 3a8 8 0 0 0 13-4',pen:'m16 3 5 5-12 12-6 1 1-6Z M14 5l5 5'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.pen}"/></svg>`;
const button=(action,label,name='',kind='secondary',extra='')=>`<button type="button" class="btn ${kind}" data-flow-action="${action}" ${extra}>${name?icon(name):''}${label}</button>`;
const escapeRE=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
export function focusMarkup(text,anchors){
 const pinned=anchors.filter(a=>a.locked).map(a=>a.text).filter(Boolean);if(!pinned.length)return esc(text);
 const expression=new RegExp('('+pinned.map(escapeRE).join('|')+')','giu');
 return String(text).split(expression).map((part,i)=>i%2?`<mark class="flow-highlight">${esc(part)}</mark>`:esc(part)).join('');
}
export function draftFlowHTML(){return '<section id="draft-flow" class="draft-flow" aria-label="Draft Flow writing workspace"></section>';}
export function mountDraftFlow(root,options){
 const context=options.context(),chapters=options.chapters();let disposed=false,frame=null,session,anchorsKey='',historyKey='',sourceKey='',previewKey='',statusKey='';
 const motion=`<svg class="flow-lines" viewBox="0 0 240 56" fill="none" aria-hidden="true"><path d="M2 42C42 42 39 14 84 14S141 44 180 29 205 13 238 13"/><path d="M2 28C45 28 49 43 84 40S141 8 180 20 207 28 238 28"/><path d="M2 14C39 14 45 27 84 27S140 43 180 40 210 43 238 43"/></svg>`;
 root.innerHTML=`<header class="flow-header"><div><span class="flow-eyebrow">YOUR WRITING ROOM</span><h1>Draft Flow<span class="flow-title-dot" aria-hidden="true">.</span></h1><p>Find the next turn. Keep the one that feels like yours.</p></div><div class="flow-model">${motion}${button('model',esc(context.model||'Choose a writing model'),'pen','secondary','aria-label="Choose the model for Draft Flow"')}</div>${button('tune','Tune','pen','secondary flow-tune-button')}</header>
 <div class="flow-layout"><div class="flow-main"><details class="flow-card flow-context" id="flow-context-card" open><summary class="flow-context-summary"><strong>Your chapter</strong><span>${esc(context.chapterTitle)}</span></summary><div class="flow-context-body"><label class="flow-chapter-label"><span class="sr-only">Chapter for Draft Flow</span><select id="flow-chapter">${chapters.map((c,i)=>`<option value="${i}" ${i===options.chapterIndex?'selected':''}>${String(i+1).padStart(2,'0')} · ${esc(c.title)}</option>`).join('')}</select></label><div class="flow-source" id="flow-source" dir="${esc(context.dir||'ltr')}" lang="${esc(context.languageCode||'en')}" tabindex="0" aria-label="Current manuscript ending"></div><div class="flow-context-tools"><span>Keep a detail in view.</span>${button('pin-selection','Pin selected words','pin','quiet')}</div></div></details>
 <section class="flow-card flow-preview-card" aria-labelledby="flow-preview-heading"><div class="flow-section-title"><div><span class="flow-eyebrow">A POSSIBLE CONTINUATION</span><h2 id="flow-preview-heading">The page ahead</h2></div><span class="flow-word-count" id="flow-word-count">0 words</span></div><div class="flow-preview" id="flow-preview" dir="${esc(context.dir||'ltr')}" lang="${esc(context.languageCode||'en')}" tabindex="0" role="region" aria-label="Uncommitted continuation preview"></div>
 <div class="flow-playhead"><div><label for="flow-playhead">Explore from this point</label><output id="flow-playhead-value" for="flow-playhead">Beginning</output></div><input id="flow-playhead" type="range" min="0" max="0" value="0" aria-describedby="flow-playhead-help"><p id="flow-playhead-help">Move the playhead, then explore. Words before it stay in the next preview.</p></div>
 <div class="flow-status" id="flow-status" role="status" aria-live="polite"></div><div class="flow-preview-actions">${button('explore','Explore a continuation','arrow','primary')}${button('alternate','Try another','refresh')}${button('stop','Stop','stop','secondary')}${button('copy','Copy preview','copy','quiet')}</div>
 <div class="flow-keep-bar"><div><strong>Your manuscript is yours.</strong><span>Only the words you keep are added to the chapter.</span></div><div class="flow-keep-actions">${button('keep-cursor','Keep to playhead','','secondary')}${button('keep','Keep preview','check','primary')}</div></div></section>
 <section class="flow-history"><label for="flow-history">Earlier directions</label><div><select id="flow-history" aria-label="Earlier writing previews"></select>${button('discard','Discard preview','close','quiet')}</div><p>Up to eight previews stay with this chapter, including in JSON backups.</p></section></div>
 <aside class="flow-controls" aria-label="Writing direction controls">${button('preview','Back to preview','arrow','secondary flow-return-button')}<section class="flow-card"><div class="flow-section-title"><h2>Set the direction</h2><span class="flow-small">Your next few lines</span></div><label class="field"><span class="sr-only">Direction for the continuation</span><textarea id="flow-direction" rows="4" maxlength="1500" placeholder="Let the silence carry the scene. Give Ada one detail she cannot explain."></textarea></label><div class="flow-axes">${flowAxes.map(a=>`<div class="flow-axis"><div><label for="flow-${a.id}">${a.name}</label><output id="flow-${a.id}-value" for="flow-${a.id}"></output></div><input type="range" id="flow-${a.id}" data-flow-axis="${a.id}" min="0" max="100" step="1"><div class="flow-range-ends"><span>${a.low}</span><span>${a.high}</span></div></div>`).join('')}</div><label class="flow-live"><span><strong>Live tuning</strong><small>Refresh the preview when you change direction.</small></span><input id="flow-live" type="checkbox" role="switch" aria-describedby="flow-session-budget"></label><p class="flow-small" id="flow-session-budget">Off until you enable it. Up to six model requests per session.</p></section>
 <section class="flow-card"><div class="flow-section-title"><h2>Story pins</h2><span class="flow-small" id="flow-pin-count">0 / 8</span></div><p class="flow-control-note">Names, objects, or phrases to emphasise in the next turn.</p><div class="flow-add-pin"><label class="sr-only" for="flow-pin">Phrase to pin</label><input id="flow-pin" type="text" maxlength="96" placeholder="The brass key" autocomplete="off">${button('add-pin','Pin','pin','secondary')}</div><div class="flow-pins" id="flow-pins"></div><p class="flow-small">Pins guide the writing prompt. Review the words the model returns.</p></section></aside></div>`;
 const find=s=>root.querySelector(s);if(globalThis.window?.matchMedia?.('(max-width:650px)').matches)find('#flow-context-card').open=false;
 function schedule(){if(disposed)return;if(session){root.dataset.phase=session.phase;root.setAttribute('aria-busy',String(session.working));}if(frame!==null)return;frame=(globalThis.requestAnimationFrame||((f)=>setTimeout(f,0)))(()=>{frame=null;if(!disposed)paint();});}
 function paint(){if(!session||disposed)return;const {data}=session,branch=session.branch,text=branch?.text||'',busy=session.working||session.keeping;
  root.dataset.phase=session.phase;root.toggleAttribute('data-live',session.live);root.setAttribute('aria-busy',String(session.working));
  const field=find('#flow-direction');if(field.value!==data.direction)field.value=data.direction;
  for(const axis of flowAxes){const value=data.axes[axis.id],label=axisLabel(axis,value),input=find('#flow-'+axis.id);input.value=String(value);input.setAttribute('aria-valuetext',`${label}, ${value} percent`);find('#flow-'+axis.id+'-value').textContent=label;input.style.setProperty('--flow-value',value+'%');}
  find('#flow-live').checked=session.live;find('#flow-session-budget').textContent=session.live?`${session.requests} of 6 model requests used. Pause whenever you like.`:'Off until you enable it. Up to six model requests per session.';
  const newAnchorKey=JSON.stringify(data.anchors.map(a=>[a.id,a.text,a.locked]));
  if(newAnchorKey!==anchorsKey){anchorsKey=newAnchorKey;find('#flow-pins').innerHTML=data.anchors.length?data.anchors.map(a=>`<div class="flow-pin" data-pin="${esc(a.id)}"><div><button type="button" class="flow-pin-toggle" data-flow-action="toggle-pin" data-id="${esc(a.id)}" aria-pressed="${a.locked}" aria-label="${a.locked?'Unpin':'Pin'} ${esc(a.text)}">${icon('pin')}<span>${esc(a.text)}</span></button><button type="button" class="flow-remove-pin" data-flow-action="remove-pin" data-id="${esc(a.id)}" aria-label="Remove ${esc(a.text)}">${icon('close')}</button></div><label class="flow-pin-weight"><span>Emphasis</span><input type="range" data-flow-weight="${esc(a.id)}" min="10" max="100" step="10" value="${a.weight}" aria-label="Emphasis for ${esc(a.text)}"><output>${a.weight}%</output></label></div>`).join(''):'<div class="flow-no-pins">Pin a detail to give it a little more presence.</div>';}
  for(const a of data.anchors){const item=[...root.querySelectorAll('[data-pin]')].find(e=>e.dataset.pin===a.id);item.querySelector('input').value=String(a.weight);item.querySelector('output').textContent=a.weight+'%';}
  find('#flow-pin-count').textContent=data.anchors.length+' / 8';
  const raw=options.context().plainText||'',newSource=JSON.stringify([raw,anchorsKey]);if(newSource!==sourceKey){sourceKey=newSource;find('#flow-source').innerHTML=raw.trim()?focusMarkup(raw.slice(-2400).trim(),data.anchors):'<span class="flow-empty-source">A fresh chapter. Begin from its outline and your direction.</span>';}
  const nextPreview=JSON.stringify([text,data.pivot,anchorsKey,session.phase]);
  if(nextPreview!==previewKey){previewKey=nextPreview;const prefix=wordPrefix(text,data.pivot);find('#flow-preview').innerHTML=text?`<span class="flow-prefix">${focusMarkup(prefix,data.anchors)}</span><span class="flow-future">${focusMarkup(text.slice(prefix.length),data.anchors)}</span>`:`<div class="flow-empty-preview">${motion}<h3>There is more than one way forward.</h3><p>Set a direction, pin a detail, and explore a possible continuation.</p><span>${esc(context.model?'Nothing is sent until you approve the model request.':'Choose a writing model to explore your next few lines.')}</span></div>`;}
  const total=words(text),playhead=find('#flow-playhead');playhead.max=String(total);playhead.value=String(Math.min(data.pivot,total));playhead.disabled=!total||session.keeping;playhead.setAttribute('aria-valuetext',`${data.pivot} of ${total} preview words retained for the next direction`);find('#flow-playhead-value').textContent=data.pivot?`${data.pivot} / ${total} words`:'Beginning';find('#flow-word-count').textContent=total+' '+(total===1?'word':'words');
  const message=session.stale?'The chapter changed after this preview. Explore again before keeping it.':session.message,key=session.phase+'|'+message;
  if(key!==statusKey){statusKey=key;find('#flow-status').textContent=message;find('#flow-status').dataset.error=String(session.phase==='error'||session.stale);}
  const newHistory=JSON.stringify(data.branches.map(b=>[b.id,b.model,b.partial]));if(newHistory!==historyKey){historyKey=newHistory;find('#flow-history').innerHTML=data.branches.length?data.branches.map((b,i)=>`<option value="${esc(b.id)}">${i===0?'Latest preview':'Earlier preview '+(i+1)}${b.partial?' · partial':''}${b.model?' · '+esc(b.model):''}</option>`).join(''):'<option value="">Your previews will appear here</option>';}
  find('#flow-history').value=data.selectedId;find('#flow-history').disabled=busy||!data.branches.length;
  for(const name of ['keep','keep-cursor'])find(`[data-flow-action="${name}"]`).disabled=busy||!text.trim()||session.stale||!session.validStamp||(name==='keep-cursor'&&!data.pivot);
  for(const name of ['copy','discard'])find(`[data-flow-action="${name}"]`).disabled=!text.trim()||session.keeping;
  find('[data-flow-action="stop"]').disabled=!session.working&&!session.live;find('[data-flow-action="alternate"]').disabled=busy||!text.trim();find('[data-flow-action="explore"]').disabled=busy;
  find('[data-flow-action="explore"]').innerHTML=icon('arrow')+(context.connected?'Explore a continuation':'Choose a writing model');
 }
 session=new DraftFlow(options.value,{context:options.context,authorise:options.authorise,persist:options.persist,apply:options.apply,onChange:schedule});
 const fail=error=>{if(disposed)return;if(session.working){options.toast?.(error?.message||'That action could not finish.');return;}session.message=error?.message||'That action could not finish.';session.phase='error';paint();};
 async function copy(){const text=session.branch?.text||'';if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);options.toast?.('Preview copied.');return;}catch{}}const field=document.createElement('textarea');field.value=text;field.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(field);field.select();let copied=false;try{copied=!!document.execCommand?.('copy');}finally{field.remove();}if(copied)options.toast?.('Preview copied.');else throw Error('Select the preview text to copy it with your device’s copy command.');}
 async function click(event){const target=event.target.closest('[data-flow-action]');if(!target||!root.contains(target)||target.disabled)return;event.preventDefault();try{const action=target.dataset.flowAction,id=target.dataset.id;
  if(action==='model'){options.chooseModel();return;}
  if(action==='tune'||action==='preview'){const target=find(action==='tune'?'.flow-controls':'.flow-preview-card');target.scrollIntoView?.({block:'start',behavior:document.documentElement.classList.contains('reduce-motion')||window.matchMedia?.('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});return;}
  if(['explore','alternate'].includes(action)){if(!options.context().connected){options.chooseModel();return;}await session.run({alternate:action==='alternate'});}
  if(action==='stop')session.stop();
  if(action==='keep'||action==='keep-cursor')await session.keep({toCursor:action==='keep-cursor'});
  if(action==='copy')await copy();if(action==='discard')session.discard();
  if(action==='add-pin'){session.addAnchor(find('#flow-pin').value);find('#flow-pin').value='';find('#flow-pin').focus();}
  if(action==='pin-selection'){const selection=window.getSelection();if(!selection||!root.contains(selection.anchorNode)||!root.contains(selection.focusNode))throw Error('Select a few words in this chapter or preview first.');session.addAnchor(selection.toString());selection.removeAllRanges();}
  if(action==='toggle-pin'){const item=session.data.anchors.find(a=>a.id===id);if(item)session.changeAnchor(id,{locked:!item.locked});}
  if(action==='remove-pin')session.changeAnchor(id,{remove:true});
 }catch(error){fail(error);}}
 function input(event){const field=event.target;if(!root.contains(field))return;event.stopPropagation();try{if(field.id==='flow-direction')session.setDirection(field.value);if(field.dataset.flowAxis)session.setAxis(field.dataset.flowAxis,field.value);if(field.dataset.flowWeight)session.changeAnchor(field.dataset.flowWeight,{weight:field.value});if(field.id==='flow-playhead')session.setPivot(field.value);}catch(error){fail(error);}}
 function change(event){event.stopPropagation();const field=event.target;if(field.id==='flow-live'){if(field.checked&&!options.context().connected){field.checked=false;options.chooseModel();return;}session.setLive(field.checked);}if(field.id==='flow-history')session.select(field.value);if(field.id==='flow-chapter')options.onChapter(Number(field.value));}
 function keydown(event){if(event.target.id==='flow-pin'&&event.key==='Enter'){event.preventDefault();void click({target:find('[data-flow-action="add-pin"]'),preventDefault(){}});}if(event.key==='Escape'&&session.working){event.preventDefault();session.stop();}if(event.key==='Enter'&&event.altKey){event.preventDefault();void click({target:find('[data-flow-action="explore"]'),preventDefault(){}});}if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();void session.keep().catch(fail);}}
 const preserveSelection=event=>{if(event.target.closest('[data-flow-action="pin-selection"]'))event.preventDefault();};
 root.addEventListener('click',click);root.addEventListener('input',input);root.addEventListener('change',change);root.addEventListener('keydown',keydown);root.addEventListener('mousedown',preserveSelection);paint();
 return {session,dispose(){if(disposed)return;session.dispose();disposed=true;if(frame!==null)(globalThis.cancelAnimationFrame||clearTimeout)(frame);root.removeEventListener('click',click);root.removeEventListener('input',input);root.removeEventListener('change',change);root.removeEventListener('keydown',keydown);root.removeEventListener('mousedown',preserveSelection);}};
}
